"""Generate crawlable, dependency-free pages for Las Olas Yacht Management."""
from pathlib import Path
import json, html, os, re, hashlib
from urllib.parse import quote, urlsplit

ROOT = Path(__file__).parent
OUT = ROOT / 'docs'
ORIGIN = os.environ.get('SITE_URL', 'https://grandpajackai.github.io/las-olas-yacht-management').rstrip('/')
BASE_PATH = urlsplit(ORIGIN).path.rstrip('/')
REVIEW_PREVIEW = os.environ.get('REVIEW_PREVIEW', '1') != '0'
ASSET_VERSION = hashlib.sha256(b''.join((OUT / 'assets' / name).read_bytes() for name in ['site.css', 'site.js'])).hexdigest()[:12]
DATA = json.loads((ROOT / 'content.json').read_text())
SERVICES, PROGRAMS = DATA['services'], DATA['programs']
ARTICLES = json.loads((ROOT / 'journal.json').read_text())
PAGES = []
SERVICE_META = {
'interior-care': 'Yacht interior care in Fort Lauderdale, from cabin cleaning and linen presentation to guest preparation. Explore a tailored approach with Las Olas.',
'exterior-detailing': 'Yacht detailing in Fort Lauderdale: washdowns, glass care, metal polishing and finish preservation, tailored to your vessel by Las Olas Yacht Management.',
'maintenance': 'Yacht maintenance in Fort Lauderdale with routine systems attention, machinery checks and service coordination. Explore vessel-specific care with Las Olas.',
'project-management': 'Plan your yacht refit or yard period in Fort Lauderdale with clear work scopes, contractor coordination and progress oversight from Las Olas.',
'captain-and-crew': 'Arrange yacht captain and crew support in Fort Lauderdale for local days, deliveries and planned cruising. Explore a tailored scope with Las Olas.',
'concierge': 'Yacht concierge in Fort Lauderdale: provisioning, marina reservations, itineraries and travel coordination, shaped around your plans by Las Olas.',
'hurricane-planning': 'Explore vessel-specific yacht hurricane planning in Fort Lauderdale, with document organization, readiness coordination and relocation arrangements.'}
PROGRAM_META = {
'essential-care': 'Essential Care brings foundational yacht cleaning and routine checks together in a tailored management program from Las Olas in Fort Lauderdale.',
'coastal-care': 'Explore Coastal Care, a tailored yacht management program combining detailed cleaning, routine checks and service coordination in Fort Lauderdale.',
'complete-management': 'Complete Management connects weekly yacht care, technical upkeep, projects and ownership logistics in one tailored Las Olas management framework.',
'sportfish-care': 'Sportfish Care is tailored to center consoles and sportfishing yachts, with regular cleaning, machinery attention and offshore readiness coordination.'}
E = html.escape
ARROW = '<span class="arrow" aria-hidden="true">↗</span>'

def button(label, url, style=''):
    return f'<a class="button {style}" href="{E(url)}">{E(label)}{ARROW}</a>'

def link(label, url):
    return f'<a class="text-link" href="{E(url)}">{E(label)}{ARROW}</a>'

def brand():
    return '<svg class="brand-wave" viewBox="0 0 60 10" fill="none" aria-hidden="true"><path d="M1 5Q15-3 30 5T59 5M8 9Q20 2 32 9T54 9" stroke="currentColor" stroke-width=".8"/></svg><span class="brand-main">LAS OLAS</span><span class="brand-sub">YACHT MANAGEMENT</span>'

def nav(current):
    items = [('Services','/services/'),('Programs','/programs/'),('Our approach','/about/'),('The journal','/journal/')]
    def links(mobile=False):
        return ''.join(f'<a href="{url}"'+(' aria-current="page"' if current.startswith(url) else '')+f'>{name}</a>' for name,url in items)
    return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap"><a class="brand" href="/" aria-label="Las Olas Yacht Management home">{brand()}</a><nav class="desktop-nav" aria-label="Main navigation">{links()}{button('Discuss your yacht','/contact/','outline header-cta')}</nav><button class="menu-toggle" id="menu-toggle" aria-expanded="false" aria-controls="mobile-menu" aria-label="Open navigation"><span></span><span></span></button></div><nav id="mobile-menu" class="mobile-menu" aria-label="Mobile navigation" inert><span class="eyebrow">Your next chapter on the water</span>{links(True)}{button('Discuss your yacht','/contact/','light')}</nav></header><noscript><style>.menu-toggle,.journey-navigation{{display:none!important}}</style><nav class="noscript-nav" aria-label="Navigation without JavaScript">{links()}{button("Discuss your yacht","/contact/")}</nav></noscript>'''

def footer():
    services = ''.join(f'<a href="/services/{s["slug"]}/">{E(s["short"])}</a>' for s in SERVICES)
    programs = ''.join(f'<a href="/programs/{p["slug"]}/">{E(p["name"])}</a>' for p in PROGRAMS)
    return f'''<footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-brand-col"><a class="brand footer-brand" href="/" aria-label="Las Olas Yacht Management home">{brand()}</a><p class="footer-intro">Considered care. Clear communication.<br>More time for the water.</p></div><div class="footer-col"><span class="eyebrow">Yacht services</span>{services}</div><div class="footer-col"><span class="eyebrow">Our programs</span>{programs}<a href="/programs/">Compare programs ↗</a></div><div class="footer-col"><span class="eyebrow">Las Olas</span><a href="/about/">Our approach</a><a href="/journal/">The journal</a><a href="/contact/">Discuss your yacht</a><p style="margin-top:25px">Fort Lauderdale, Florida<br>South Florida yacht care</p></div></div><div class="footer-bottom"><span>© 2026 Las Olas Yacht Management. All rights reserved.</span><div class="footer-legal"><a href="/privacy/">Privacy</a><a href="/accessibility/">Accessibility</a><a href="/sitemap/">Sitemap</a></div><span>MADE FOR LIFE ON THE WATER</span></div></div></footer>'''

def cta():
    return f'''<section class="cta-section"><div class="wrap"><div><span class="eyebrow">A conversation is the first step</span><h2>A better way<br>to own the <em>moment.</em></h2><p>Tell us about your yacht. Let’s shape the care around you.</p></div>{button('Let’s discuss your yacht','/contact/')}</div></section>'''

def inner_hero(eyebrow, title, intro, crumbs=None):
    bc = '<a href="/">Home</a>'
    for label,url in (crumbs or []):
        bc += '<span aria-hidden="true">/</span>' + (f'<a href="{url}">{E(label)}</a>' if url else f'<span>{E(label)}</span>')
    return f'''<section class="inner-hero"><div class="wrap"><nav class="breadcrumb" aria-label="Breadcrumb">{bc}</nav><span class="eyebrow">{E(eyebrow)}</span><h1>{title}</h1><p>{E(intro)}</p></div></section>'''

def page(path, title, desc, body, schema=None):
    url = ORIGIN + path
    base_schema = {'@context':'https://schema.org','@graph':[
        {'@type':'Organization','@id':ORIGIN+'/#organization','name':'Las Olas Yacht Management','url':ORIGIN+'/'},
        {'@type':'WebSite','@id':ORIGIN+'/#website','name':'Las Olas Yacht Management','url':ORIGIN+'/'},
        {'@type':'WebPage','@id':url+'#webpage','url':url,'name':title,'description':desc,'isPartOf':{'@id':ORIGIN+'/#website'}}]}
    if path != '/':
        segments = path.strip('/').split('/')
        crumbs=[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'}]
        for i,seg in enumerate(segments):
            crumbs.append({'@type':'ListItem','position':i+2,'name':seg.replace('-',' ').title(),'item':ORIGIN+'/'+'/'.join(segments[:i+1])+'/'})
        base_schema['@graph'].append({'@type':'BreadcrumbList','itemListElement':crumbs})
    if schema: base_schema['@graph'].append(schema)
    schema_json = json.dumps(base_schema, separators=(',', ':')).replace('<', chr(92)+'u003c')
    doc = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><meta name="theme-color" content="#062f35"><link rel="canonical" href="{url}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="preload" href="/assets/serif-regular.ttf" as="font" type="font/ttf" crossorigin><link rel="preload" href="/assets/sans-regular.ttf" as="font" type="font/ttf" crossorigin><meta property="og:type" content="website"><meta property="og:site_name" content="Las Olas Yacht Management"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/ocean-hero.webp"><meta property="og:image:alt" content="A white motor yacht moving through deep teal ocean water"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/assets/site.css">{'<meta name="robots" content="noindex">' if path == '/404/' else ''}<script type="application/ld+json">{schema_json}</script><script src="/assets/site.js" defer></script></head><body>{nav(path)}<main id="main">{body}</main>{footer()}</body></html>'''
    # GitHub project Pages is hosted below a repository path. Keep every local
    # route, image, icon and preload inside that prefix, including the 404 page.
    if BASE_PATH:
        doc = re.sub(r'(\b(?:href|src)=\")/(?!/)', lambda match: match[1] + BASE_PATH + '/', doc)
    for asset in ['site.css', 'site.js']:
        doc = doc.replace('/assets/' + asset + '"', '/assets/' + asset + '?v=' + ASSET_VERSION + '"')
    if REVIEW_PREVIEW and path != '/404/':
        doc = doc.replace('</head>', '<meta name="robots" content="noindex, nofollow"></head>')
    dest=OUT / path.strip('/') / 'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(doc)
    PAGES.append(path)

def service_cards(feature=False, heading=3):
    cards=''
    descriptions=['Beautifully composed spaces, from the first welcome to the last detail.','A considered approach to salt, sun, and a flawless first impression.','Routine attention to the systems that make every day aboard possible.','Clear coordination for yard periods, repairs, and your next upgrade.','The right support for a local escape or the next passage.','Travel, provisioning, and the little things that make a day your own.','Vessel-specific preparation, with the responsibilities clearly arranged.']
    for i,s in enumerate(SERVICES):
        cards+=f'<a class="service-card" href="/services/{s["slug"]}/"><span class="service-number">0{i+1}</span>{ARROW}<h3>{E(s["short"])}</h3><p>{descriptions[i]}</p></a>'
    if feature:
        cards+=f'''<div class="service-card feature"><img class="feature-image" src="/assets/yacht-detail.webp" alt="Teak deck and ivory seating on a luxury yacht" loading="lazy" width="1672" height="941"><div><span class="eyebrow gold">A plan as individual as your yacht</span><h3>Everything connected.<br>Every detail considered.</h3><p>Bring the right services together in one thoughtful management plan.</p>{link('Explore the programs','/programs/')}</div></div>'''
    return '<div class="service-grid">'+cards.replace('<h3>',f'<h{heading}>').replace('</h3>',f'</h{heading}>')+'</div>'

def articles_grid(heading=3):
    return '<div class="journal-grid">'+''.join(f'''<article class="journal-card"><span class="eyebrow">{E(a['category'])} &nbsp; / &nbsp; {E(a['readTime'])}</span><h{heading}><a href="/journal/{a['slug']}/">{E(a['title'])}</a></h{heading}><p>{E(a['excerpt'])}</p>{link('Read the story','/journal/'+a['slug']+'/')}</article>''' for a in ARTICLES)+'</div>'

