ribbon='<div class="service-ribbon"><div class="wrap">'+''.join('<span>'+E(label)+'</span>'+('<b aria-hidden="true">·</b>' if i<4 else '') for i,label in enumerate(['BESPOKE YACHT CARE','MAINTENANCE & SYSTEMS','CAPTAIN & CREW','CONCIERGE','FORT LAUDERDALE']))+'</div></div>'
