programs_home='''<section class="programs-section"><div class="wrap"><div class="section-head reveal"><div><span class="eyebrow">04 / Care that fits your course</span><h2>Personal by design.<br><em>Comprehensive by choice.</em></h2></div>'''+link('Compare programs','/programs/')+'</div>'+tabs+'</div>'+panels+'</div></section>'
approach='''<section class="approach-block"><div class="approach-photo"><img src="/assets/yacht-detail.webp" alt="Warm teak, ivory seating, and polished railings on a yacht’s aft deck" loading="lazy" width="1672" height="941"><span class="photo-caption">A considered life on the water · Illustrative imagery</span></div><div class="approach-text"><span class="eyebrow gold">05 / The Las Olas approach</span><h2>Quiet confidence.<br><em>In every detail.</em></h2><p>Good management should make ownership feel simpler. Our approach is built around the things that matter between one day aboard and the next.</p><div class="values"><div class="value"><span>01</span><div><h3>Care with intention.</h3><p>A vessel-specific plan, with the details considered together.</p></div></div><div class="value"><span>02</span><div><h3>Clarity at every step.</h3><p>Useful updates, defined responsibilities, and informed decisions.</p></div></div><div class="value"><span>03</span><div><h3>Your plans come first.</h3><p>A rhythm of care shaped around how you spend time aboard.</p></div></div></div>'''+link('Get to know Las Olas','/about/')+'''</div></section>'''
journal_home='''<section class="journal-section"><div class="wrap"><div class="section-head reveal"><div><span class="eyebrow">06 / The journal</span><h2>A little perspective.<br><em>A better experience.</em></h2></div>'''+link('Explore the journal','/journal/')+'</div>'+articles_grid()+'</div></section>'
