    body+='<section class="content-section"><article class="wrap article-body"><span class="eyebrow">Las Olas / Ownership perspectives</span>'+''.join('<section><h2>'+E(x['heading'])+'</h2><p>'+E(x['body'])+'</p></section>' for x in a['sections'])+'<div style="margin-top:45px">'+link('Return to the journal','/journal/')+'</div></article></section>'+cta()
