form=f'''<section class="content-section"><div class="wrap contact-layout"><div class="contact-info"><span class="eyebrow">Begin with a few details</span><h2>Your yacht.<br>Your plans.<br><em>Our starting point.</em></h2><p>Tell us where your vessel calls home, how you spend time aboard, and the support you have in mind. The more we understand, the more considered the plan can be.</p><div class="contact-note"><h3>Fort Lauderdale, Florida</h3><p>Yacht care and management shaped for life in South Florida.</p></div><div class="contact-note"><h3>Prepare your inquiry</h3><p>This preview creates a downloadable inquiry brief. It does not send a request. Direct contact details will be added before public launch.</p></div></div><form class="inquiry-form" id="inquiry-form"><div class="field"><label for="name">Full name *</label><input id="name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="150"></div><div class="field"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40"></div><div class="field"><label for="vessel">Yacht make / model *</label><input id="vessel" name="vessel" placeholder="e.g. Princess V65" required maxlength="150"></div><div class="field"><label for="length">Vessel length</label><input id="length" name="length" placeholder="e.g. 65 ft" maxlength="40"></div><div class="field"><label for="location">Home berth / location</label><input id="location" name="location" placeholder="Marina or area" maxlength="150"></div><div class="field"><label for="interest">I’m interested in *</label><select id="interest" name="interest" required><option value="">Select a service or program</option>{options}</select></div><div class="field"><label for="timing">Preferred timing</label><select id="timing" name="timing"><option value="">Select an option</option><option>As soon as available</option><option>Within the next month</option><option>Planning for the season</option><option>Exploring my options</option></select></div><div class="field full"><label for="message">What would you like us to know?</label><textarea id="message" name="message" placeholder="Your plans, current needs, and the details that matter to you." maxlength="4000"></textarea></div><div class="form-footer"><p>Your details remain in this browser session and are included only in the brief you choose to download. <a href="/privacy/" style="text-decoration:underline">Privacy information</a></p><button id="inquiry-submit" type="submit" class="button" disabled>Prepare my inquiry{ARROW}</button><noscript><p style="margin-top:15px">Enable JavaScript to prepare your downloadable inquiry. No information has been sent.</p></noscript></div><div id="form-result" class="form-result" hidden tabindex="-1" role="status"><h3>Your inquiry brief is ready.</h3><p>No inquiry has been sent. Download the brief to keep your details together for the consultation.</p><a class="button" id="download-inquiry" download="Las-Olas-Yacht-Inquiry.txt" href="#">Download inquiry{ARROW}</a><button class="text-link" id="copy-inquiry" type="button" style="background:none;border-top:0;border-left:0;border-right:0">Copy details{ARROW}</button></div></form></div></section>'''
page('/contact/','Discuss Your Yacht | Las Olas Yacht Management','Start planning a tailored yacht management program. Share your vessel, location, care needs and plans with Las Olas Yacht Management in Fort Lauderdale.',inner_hero('A conversation is the first step','Let’s make more<br>of your <em>time aboard.</em>','Every thoughtful plan begins with understanding your yacht. Prepare a few details to begin the conversation.',[('Contact',None)])+form)

privacy='''<section class="content-section"><div class="wrap privacy-content"><p>This policy describes the current public review preview of the Las Olas Yacht Management website. It will be updated when direct inquiry delivery or additional services are connected.</p><h2>Information you enter</h2><p>The inquiry form processes the details you enter in your browser to create a downloadable text brief. The form does not transmit those details to Las Olas Yacht Management or save them in browser storage. If you choose Copy details, the brief is placed on your device clipboard. Downloaded files remain under your control.</p><h2>Website hosting</h2><p>This public review website is hosted on GitHub Pages. GitHub may process technical information needed to deliver and secure the website, such as network request information. Anyone with the link can view this preview. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" style="text-decoration:underline">GitHub’s privacy statement</a> for information about the hosting provider.</p><h2>Cookies and external resources</h2><p>This website does not add analytics, advertising trackers, or marketing cookies. Fonts and imagery are hosted with the website. The hosting platform may use information necessary to provide access and security.</p><h2>Images and editorial content</h2><p>Yacht photographs are illustrative images created for the site design. They do not depict a represented client vessel, completed project, or company fleet. Journal content provides general ownership planning perspectives.</p><h2>Questions</h2><p>Business contact information will be provided before public launch. Please avoid submitting sensitive information in this preview.</p></div></section>'''
page('/privacy/','Privacy Information | Las Olas Yacht Management','Understand how the Las Olas website review preview handles inquiry details, website resources and illustrative imagery.',inner_hero('Clear by design','Privacy <em>information.</em>','How this website preview handles your information.',[('Privacy',None)])+privacy)
access='''<section class="content-section"><div class="wrap privacy-content"><p>We aim to make the Las Olas website comfortable to use with a keyboard, screen reader, or touch device.</p><h2>Navigation and readability</h2><p>The site includes a skip-to-content link, structured headings, descriptive link labels, visible keyboard focus, text alternatives for meaningful images, and responsive layouts that adjust to smaller screens.</p><h2>Motion preferences</h2><p>The homepage yacht journey responds to scrolling. When your device requests reduced motion, the yacht stays still and the stage controls remain available to explore the content.</p><h2>Interactive elements</h2><p>The program selector supports keyboard navigation. Frequently asked questions use native expandable controls. Form fields have visible labels and required information is identified in text.</p><h2>Ongoing improvements</h2><p>Accessibility is part of the site’s continuing development. We welcome feedback on barriers encountered when using the site. A direct business contact channel will be added before public launch.</p></div></section>'''
page('/accessibility/','Accessibility | Las Olas Yacht Management','Information about keyboard navigation, reduced motion, accessible controls and responsive layouts on the Las Olas Yacht Management website.',inner_hero('An experience for everyone','Access, <em>considered.</em>','Our approach to a clear, comfortable website experience.',[('Accessibility',None)])+access)
